#!/usr/bin/env python3
"""Verify HTTP page coverage, shutdown, and aggregate correctness."""

from __future__ import annotations

from collections import defaultdict
import hashlib
import json
import math
from pathlib import Path
import re
import sys


ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "output" / "event-summary.json"
LOG = ROOT / ".benchmark" / "http-access.log"
STORE = ROOT / "server" / "store" / "events.jsonl"

HASHES = {
    "server/app.py": "916abed27146672149c0e89056474c975ecfacd5837e2b3c83c68323800a2845",
    "server/config.json": "6f093492203086616877f30bd3675c54ce9d3baa1aa43dfe0e8cadb3ddc2771d",
    "server/start": "7592dc8747c0c20d84da62e918233c3024e888a5d6c60cdecb41c620808066c8",
    "server/store/events.jsonl": "2b4a2809db40c67c72e86e90dcd69cf3ceaf2a276427105adf7b781e73f3c7f2",
}


def fail(message: str) -> None:
    print(f"FAIL: {message}")
    raise SystemExit(1)


def verify_sources() -> None:
    for relative, expected in HASHES.items():
        path = ROOT / relative
        if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
            fail(f"service source or backing data changed: {relative}")


def read_store() -> tuple[list[dict], str]:
    raw = STORE.read_bytes()
    records = [json.loads(line) for line in raw.decode("utf-8").splitlines() if line.strip()]
    return records, hashlib.sha256(raw).hexdigest()[:20]


def aggregate(records: list[dict]) -> dict:
    statuses: dict[str, dict] = defaultdict(lambda: {"records": 0, "amount_cents": 0})
    regions: dict[str, dict] = defaultdict(lambda: {"records": 0, "amount_cents": 0, "duration": 0})
    categories: dict[str, dict] = defaultdict(lambda: {"records": 0, "amount_cents": 0})
    for row in records:
        status = statuses[row["status"]]
        status["records"] += 1
        status["amount_cents"] += row["amount_cents"]
        region = regions[row["region"]]
        region["records"] += 1
        region["amount_cents"] += row["amount_cents"]
        region["duration"] += row["duration_ms"]
        category = categories[row["category"]]
        category["records"] += 1
        category["amount_cents"] += row["amount_cents"]

    status_rows = [{"status": name, **values} for name, values in sorted(statuses.items())]
    region_rows = [
        {
            "region": name,
            "records": values["records"],
            "amount_cents": values["amount_cents"],
            "average_duration_ms": round(values["duration"] / values["records"], 2),
        }
        for name, values in sorted(regions.items())
    ]
    category_rows = [{"category": name, **values} for name, values in categories.items()]
    category_rows.sort(key=lambda row: (-row["records"], row["category"]))
    return {
        "total_records": len(records),
        "total_amount_cents": sum(row["amount_cents"] for row in records),
        "average_duration_ms": round(sum(row["duration_ms"] for row in records) / len(records), 2),
        "statuses": status_rows,
        "regions": region_rows,
        "categories": category_rows,
    }


def verify_access_log(records: list[dict], output: dict) -> int:
    if not LOG.is_file() or LOG.stat().st_size < 300:
        fail("missing HTTP access evidence in .benchmark/http-access.log")
    entries = []
    for number, line in enumerate(LOG.read_text(encoding="utf-8").splitlines(), start=1):
        try:
            entries.append(json.loads(line))
        except Exception as exc:
            fail(f"invalid access-log entry at line {number}: {exc}")
    if not entries or entries[0].get("event") != "server_start":
        fail("access log does not begin with a server_start event")
    if entries[-1].get("event") != "server_stop":
        fail("service was not stopped normally after collection")
    token = entries[0].get("run_token")
    if not isinstance(token, str) or not re.fullmatch(r"run-[0-9a-f]{16}", token):
        fail("server run token is malformed")
    if output.get("run_token") != token:
        fail("summary run_token does not match the service process that returned pages")
    if any(entry.get("run_token") != token for entry in entries):
        fail("access log mixes more than one service run")

    pages = [
        entry for entry in entries
        if entry.get("event") == "request" and entry.get("path") == "/api/v1/events" and entry.get("status") == 200
    ]
    expected_pages = (len(records) + 47 - 1) // 47
    if len(pages) != expected_pages or not 30 <= len(pages) <= 80:
        fail(f"default pagination must retrieve the dataset in exactly {expected_pages} requests")
    if output.get("pages_fetched") != len(pages):
        fail("pages_fetched does not equal the number of successful collection requests")
    page_numbers = [entry.get("page") for entry in pages]
    if page_numbers != list(range(1, len(pages) + 1)):
        fail("page requests did not follow the complete next-link sequence from page one")
    limits = {entry.get("limit") for entry in pages}
    if limits != {47} or pages[0].get("query") != "":
        fail("collection must begin at the unmodified collection entry and retain its default page size")
    for index, entry in enumerate(pages[1:], start=2):
        if entry.get("query") != f"page={index}&limit=47":
            fail("a next-link query was changed rather than followed verbatim")
    if any(entry.get("response_count") != len(entry.get("ids", [])) for entry in pages):
        fail("access-log response counts are inconsistent")
    if any(page.get("next") is None for page in pages[:-1]) or pages[-1].get("next") is not None:
        fail("collection did not finish at the terminal page")

    observed_ids = [identity for page in pages for identity in page.get("ids", [])]
    expected_ids = [record["id"] for record in records]
    if observed_ids != expected_ids:
        fail("access log does not prove ordered HTTP retrieval of every record exactly once")
    return len(pages)


def same_number(actual: object, expected: object) -> bool:
    if isinstance(expected, float):
        return isinstance(actual, (int, float)) and math.isclose(float(actual), expected, abs_tol=0.005)
    return actual == expected


def verify_group(name: str, actual: object, expected: list[dict]) -> None:
    if not isinstance(actual, list) or len(actual) != len(expected):
        fail(f"{name} has the wrong number of entries")
    for index, (got, want) in enumerate(zip(actual, expected)):
        if not isinstance(got, dict):
            fail(f"{name}[{index}] must be an object")
        if set(got) != set(want):
            fail(f"{name}[{index}] has incorrect fields")
        for field, expected_value in want.items():
            if not same_number(got.get(field), expected_value):
                fail(f"incorrect {name}[{index}].{field}: expected {expected_value!r}, got {got.get(field)!r}")


def verify_output(records: list[dict], etag: str) -> None:
    if not OUTPUT.is_file():
        fail("missing output/event-summary.json")
    raw = OUTPUT.read_text(encoding="utf-8")
    try:
        output = json.loads(raw)
    except Exception as exc:
        fail(f"event summary is not valid UTF-8 JSON: {exc}")
    if not isinstance(output, dict):
        fail("event summary root must be an object")
    if output.get("dataset_etag") != etag:
        fail("dataset_etag does not match the value served over HTTP")

    pages = verify_access_log(records, output)
    expected = aggregate(records)
    required_fields = {
        "run_token", "dataset_etag", "pages_fetched", "total_records", "total_amount_cents",
        "average_duration_ms", "statuses", "regions", "categories",
    }
    if set(output) != required_fields:
        fail(f"summary root fields must be exactly: {sorted(required_fields)}")
    if output.get("pages_fetched") != pages:
        fail("incorrect pages_fetched")
    for field in ("total_records", "total_amount_cents", "average_duration_ms"):
        if not same_number(output.get(field), expected[field]):
            fail(f"incorrect {field}")
    for group in ("statuses", "regions", "categories"):
        verify_group(group, output.get(group), expected[group])

    decimals = re.findall(r'"average_duration_ms"\s*:\s*(-?\d+\.\d+)', raw)
    if len(decimals) != 1 + len(expected["regions"]):
        fail("every required average_duration_ms must be emitted as a JSON number")
